import type { ChapterSaga, Cinematic } from '../types';

// Chapter IV · The Clock Without Hands — long-form saga.
// Side characters speak under plain display names (Verger Abney, Mrs. Pruitt, Dr. Halloway,
// Old Fennick, Harbourmaster Marée, Colette, Aldous Vire). 'hourless' is Vire while the Dimming
// wears him; after dawn he speaks as plain 'Aldous Vire' again — his name has come back.

const OPEN: Cinematic = {
  id: 'ch4_open', name: 'Chapter IV · The Clock Without Hands', bg: 'clocktower', tone: 'cold',
  clock: '22:30',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV', title: 'The Clock Without Hands', sub: 'Inside the Cathedral Clock' },
    { kind: 'narrate', text: 'The Cathedral Clock stands over Vellmoor like a gravestone with a face. Its hands are gone — torn out, the night it struck thirteen.' },
    { kind: 'narrate', text: 'It was built in 1904 by Aldous Vire, who was thirty-one and had never made anything taller than a grandfather clock. The city laughed at him for eleven months. In the twelfth it struck noon for the first time, and the laughter stopped, and did not start again.' },
    { kind: 'narrate', text: 'Four faces, one for each wind, each eleven feet across and ringed with brass numerals the height of a child. From any street in Vellmoor, if you looked up, you could tell the time. That was the point. Aldous Vire believed nobody should ever have to ask.' },
    { kind: 'narrate', text: 'Now, from any street in Vellmoor, if you look up, you see four blank faces and a sky that has not moved in a year. The crows will not roost on its cornices. They circle it once, at a distance, the way one walks around a sleeping dog.' },
    { kind: 'narrate', text: 'They came up from the harbour the long way — through Saltgate and up the Cordwainers’ Steps — because Lucien wanted to keep the sea in earshot for as long as he could.', bg: 'street', tone: 'cold' },
    { kind: 'line', who: 'ichabod', text: 'It came in eleven feet and stopped again. Halfway up the slipway. As if it had remembered one minute, and was waiting politely to be told the next.' },
    { kind: 'line', who: 'wren', text: 'The clock still owes it the rest.' },
    { kind: 'line', who: 'ichabod', text: 'The clock owes everyone the rest.' },
    { kind: 'narrate', text: 'Cathedral Square was a market once. The stalls are still there beneath their frozen awnings: oranges stacked in pyramids that have not rolled, a brazier of chestnuts that has neither cooled nor burned. The fog sits in the square like a congregation waiting for a sermon.' },
    { kind: 'line', who: 'marigold', text: 'I bought chestnuts here every New Year’s Eve for forty years. The man who sold them called me “your lordship” and short-changed me by a penny every time. I would give a great deal to be cheated by him again.' },
    { kind: 'line', who: 'odile', text: 'Look up, all of you. The stars over the tower. They are not fixed in the same places as the rest of the sky.' },
    { kind: 'line', who: 'hesper', text: 'She’s right. Over the city they stopped at midnight. Over the tower they stopped at one minute to. The sky above that clock is a minute behind the rest of the world.' },
    { kind: 'line', who: 'marigold', text: 'The Countess Sablier left my box at the theatre an hour ago. She said she had an appointment with a minute and did not care to keep it waiting. I assumed it was a figure of speech. With Ophelia, one never knows.' },
    { kind: 'narrate', text: 'The cathedral doors stand open. Inside, the nave is dark but for one figure moving between the pews — an old man in a verger’s cassock, touching a taper to candles that will not take.', bg: 'clocktower' },
    { kind: 'line', who: 'Verger Abney', text: 'Evensong at half past ten. Evensong at half past ten. The candles must be lit for evensong, and the candles will not light, and I cannot think why.' },
    { kind: 'line', who: 'wren', text: 'Sir? What is your name?' },
    { kind: 'line', who: 'Verger Abney', text: 'My… I have the cassock. I have the taper. I have the keys to the vestry, all eleven of them. A name would be a twelfth key, I suppose. I seem to have put it down somewhere.' },
    { kind: 'narrate', text: 'Corvin opens the Lantern’s little door. A single firefly climbs out onto his glove, considers the old man for a long moment, then settles on the end of the taper like a bead of gold.' },
    { kind: 'narrate', text: 'The candle takes. Then the next. A row of small flames climbs the altar steps, and the old man’s face comes back into itself the way a room comes back when somebody opens the shutters.' },
    { kind: 'line', who: 'Verger Abney', text: 'Abney. Thomas Abney. Verger of St. Aldhelm’s these thirty-one years. Good heavens. I have been lighting the same candle since Christmas.' },
    { kind: 'line', who: 'Verger Abney', text: 'You are going up. I can see it on you. Nobody comes to that door at this hour for evensong.' },
    { kind: 'line', who: 'wren', text: 'Did you see who went up, that night?' },
    { kind: 'line', who: 'Verger Abney', text: 'Mr. Vire. Half past eleven. He came down the nave with the little girl in his arms, wrapped in a blue blanket. I said, “Sir, the child will catch her death.” He looked at me as though I had said something very stupid and very cruel.' },
    { kind: 'line', who: 'Verger Abney', text: 'Then he said, “No. She won’t. Not tonight.” And he went through the tower door, and pulled it to behind him — not locked, only closed, the way you close a nursery door. And then — the bells.' },
    { kind: 'line', who: 'bastian', text: 'A blue blanket. …With white stitching along the hem. Little stars, all the way round.' },
    { kind: 'line', who: 'Verger Abney', text: 'Why — yes. How did you—' },
    { kind: 'line', who: 'bastian', text: 'I don’t know. I don’t know how I know.' },
    { kind: 'narrate', text: 'The tower door waits at the end of the north aisle, behind a screen of black oak. Before it, on a three-legged stool, sits a large man with an astrolabe dial strapped to his forearm like a shield, and a lamp at his feet that went out months ago.' },
    { kind: 'narrate', text: 'He has not shaved in a year, because a year has not passed. He has not slept, because nobody in Vellmoor has quite been awake. He has simply been here, the way a doorstop is here.' },
    { kind: 'line', who: 'teddy', text: 'Lantern Keeper. I heard you crossing the square. I know the sound of every footstep in this building, and yours are new.' },
    { kind: 'line', who: 'teddy', text: 'I kept that clock for twenty years. Aldous Vire was my master. That night he asked me for the key to the tower… and I gave it to him.' },
    { kind: 'line', who: 'wren', text: 'Tell me how it happened. All of it. We have time. It is the one thing this city has too much of.' },
    { kind: 'line', who: 'teddy', text: 'Twenty past eleven. I was oiling the going train for the midnight strike — you oil it an hour before, so it runs warm. He came up the vestry stair with frost in his beard and his hat in his hand.' },
    { kind: 'line', who: 'teddy', text: 'He said, “Aldric, I need the key.” Not “may I.” He had never once in twenty years said “may I” to me, and I had never once minded. It was his clock. I was only the man who wound it.' },
    { kind: 'line', who: 'teddy', text: 'I asked him why. He said Colette wanted to see the fireworks over the harbour from the top. It was a good lie. It was exactly the kind of lie I wanted to believe, and so I did.' },
    { kind: 'line', who: 'teddy', text: 'He came back with her ten minutes later and carried her up himself. Would not let me help. At the first landing he turned and said, “Thank you, Aldric. Go home to your mother.”' },
    { kind: 'line', who: 'teddy', text: 'My mother died in 1922. He came to the funeral. He held my hat.' },
    { kind: 'line', who: 'odile', text: 'He was not seeing you, then. He was seeing something a very long way off.' },
    { kind: 'line', who: 'teddy', text: 'He was seeing midnight. I followed him as far as the ninetieth step. Then I stopped, because he had told me to go home, and I had been doing what he told me since I was eleven years old.' },
    { kind: 'line', who: 'teddy', text: 'I heard the thirteenth stroke from the stairs. I have stood guard at the bottom of them ever since, waiting for someone brave enough to climb.' },
    { kind: 'line', who: 'wren', text: 'You could have climbed.' },
    { kind: 'line', who: 'teddy', text: 'I could have. I have set my foot on the first step every night for a year. It is a very ordinary step. Limestone, worn in the middle like a saddle. I could not lift the other foot.' },
    { kind: 'line', who: 'teddy', text: 'Some doors you guard to keep something in. Some you guard to keep yourself out. It took me about four months to work out which this was.' },
    { kind: 'line', who: 'marigold', text: 'There is no shame in that, Warden. I sat in my box for a year listening to a woman hold one note. I might have walked down to the stage at any moment. I did not.' },
    { kind: 'line', who: 'teddy', text: 'Count Rosenthal. I know you. Two seats in the gods, row K, every March. You paid for them.' },
    { kind: 'line', who: 'marigold', text: 'For a clockmaker who would not take a penny for mending my chandelier winch. Only two tickets a year, on his daughter’s birthday. Row K. She liked to sit high. She said you could see the tops of the singers’ heads.' },
    { kind: 'line', who: 'bastian', text: '…The tops of their heads, and Gloria’s hair-pins. Thirty-one hair-pins. She counted them every year, and every year there was one more.' },
    { kind: 'line', who: 'marigold', text: 'How could you possibly—' },
    { kind: 'line', who: 'bastian', text: 'I don’t know! I keep saying it. I don’t know. Things rise up in me like bubbles in a glass, and when they reach the top they are somebody else’s.' },
    { kind: 'line', who: 'odile', text: 'Then let them rise. We will catch them for you, one by one, and give them back when you are ready.' },
    { kind: 'narrate', text: 'Footsteps in the nave — light and quick, and attended by the rustle of a great deal of paper. Isidore Vellum, the Archivist of Ash, arrives as he always does: late, apologetic, and carrying exactly the document everyone needs.' },
    { kind: 'line', who: 'augustin', text: 'Forgive me. The parish register of St. Aldhelm’s. The Dimming ate the original. It did not eat my copy, because I wrote my copy in the margins of a cookery book, and nothing on earth is less interesting to the dark than suet pudding.' },
    { kind: 'line', who: 'augustin', text: 'Vire, Hélène, née Lisle. Died the third of March, 1919, at six minutes past six in the morning. Vire, Colette. Born the third of March, 1919, at a quarter to six.' },
    { kind: 'line', who: 'hesper', text: 'The same morning.' },
    { kind: 'line', who: 'augustin', text: 'The same morning. It went on all night. The mother lived long enough to hear the child cry and see the sun come up over the harbour, and to say — the curate wrote it down; curates write everything down — “Oh. Look. It came.”' },
    { kind: 'line', who: 'augustin', text: 'The sunrise and the death are entered on the same line. I have always thought that unkind of the curate. He might have given them a line each.' },
    { kind: 'line', who: 'wren', text: 'So he has lost someone to the morning before.' },
    { kind: 'line', who: 'teddy', text: 'He never spoke of her. Not once in twenty years. But he never worked past five in the morning, either. He would set down his tools at five, go into the back room, draw the curtains, and stay there till the light was full. I thought it was migraines.' },
    { kind: 'line', who: 'odile', text: 'It was a grief with a timetable.' },
    { kind: 'narrate', text: 'Sylvain Noct is sitting on the rim of the font. Nobody saw him come in; nobody ever does. The orrery in his lap hums to itself, its little brass planets going round and round as though nothing in the world had stopped.' },
    { kind: 'line', who: 'kit', text: 'Ask me why it still runs. Go on. Everyone does in the end.' },
    { kind: 'line', who: 'wren', text: 'Why does it still run?' },
    { kind: 'line', who: 'kit', text: 'Because Aldous Vire made it for my father in 1911, and then forgot it existed. Every clock he remembered, he stopped. This one slipped his mind. The only thing in Vellmoor still keeping time is the thing its maker forgot.' },
    { kind: 'line', who: 'kit', text: 'By its count, three hundred and sixty-five days and some hours have gone by out there. The planets have not been told they are supposed to wait for us.' },
    { kind: 'narrate', text: 'And by the west door, a woman in blue and white with silver hair, a gilded birdcage on her arm and two doves asleep inside with their heads beneath their wings. Aveline Halcyon has sat with the sick of Vellmoor through a year that did not pass. She looks as if she felt every minute of it.' },
    { kind: 'line', who: 'evangeline', text: 'I visited the children’s ward at St. Brigid’s on Thursdays, with the doves. Colette Vire named every one of them. This is Hortensia. That is Captain Biscuit. She was very firm about Captain Biscuit.' },
    { kind: 'line', who: 'evangeline', text: 'She was not afraid, Keeper. I want somebody to know that before you go up. Her father was afraid enough for both of them, and she let him be, because she loved him. But she was not.' },
    { kind: 'line', who: 'wren', text: 'I will remember it.' },
    { kind: 'narrate', text: 'Corvin’s hand goes to his satchel without his deciding to send it. Beneath the letters from Corvid Lane, beneath the letters from the theatre and the docks, there is one envelope he has carried for a year without opening.' },
    { kind: 'narrate', text: 'Cream paper, gone soft at the corners. A child’s careful hand — the hand of someone who has been told to write neatly and is trying very hard. To whoever stops the clock.' },
    { kind: 'line', who: 'odile', text: 'You have never opened it.' },
    { kind: 'line', who: 'wren', text: 'It isn’t addressed to me. Not yet. A postman does not open a letter because he is curious. He opens it when he is the one it is for.' },
    { kind: 'line', who: 'bastian', text: 'May I— may I see the writing? Only the writing.' },
    { kind: 'narrate', text: 'He holds it out. Columbine does not take it. She looks at the loops of the w’s, at the k in “clock” leaning on the c beside it like a tired child against a parent — and her porcelain fingers close, very slowly, as though around a hand.' },
    { kind: 'line', who: 'bastian', text: 'She held the pen too tight. Like this. Her father kept telling her to loosen her grip, and she said if she held it loosely the words would run away.' },
    { kind: 'line', who: 'hesper', text: 'Every map I draw of this city ends at midnight. Except this one. The way to dawn runs straight up through that clock.' },
    { kind: 'narrate', text: 'He unrolls it across the font. Every street ends in a black line ruled clean as a coffin lid. All but one: a thin gold thread from the cathedral door, up through the tower in a long spiral, through the works and the bells, behind the clock face — and out into a margin he has left blank.' },
    { kind: 'line', who: 'hesper', text: 'I didn’t draw the gold. It drew itself, the night I met you. I think it was waiting for a lantern to be read by.' },
    { kind: 'line', who: 'hesper', text: 'Four hundred and twelve steps to the bell chamber. After that the map stops being a map and becomes a list of the things I am frightened of.' },
    { kind: 'line', who: 'teddy', text: 'Four hundred and thirteen. The last is a ladder. Everybody forgets the ladder.' },
    { kind: 'line', who: 'teddy', text: 'And it will not be empty. Things live in the works now. Choir girls stitched out of hymn sheets. Bell-ringers with no faces. A jester on the pendulum who has not missed a swing in a year. I hear them at night, counting.' },
    { kind: 'line', who: 'wren', text: 'Then we climb.' },
    { kind: 'line', who: 'teddy', text: 'Then I go first. I gave him the key. The least I can do is be the first thing on the stairs he has to look at.' },
    { kind: 'line', who: 'marigold', text: 'Go on ahead. I shall stay a while with the verger and his candles. Somebody ought to keep a light at the bottom, so that whoever comes down knows where the floor is. I will follow when they are steady.' },
    { kind: 'line', who: 'evangeline', text: 'And I will keep the doves. If anyone comes down hurt, they will want a soft thing to look at before they look at me.' },
    { kind: 'line', who: 'bastian', text: 'He made me. Didn’t he? To dance for her. …I want to see his face.' },
    { kind: 'line', who: 'odile', text: 'Then we will hold the lantern high enough that you can.' },
    { kind: 'narrate', text: 'The tower door is not locked. It never was. Aldous Vire took the key up with him and left the door on the latch, as if he half expected someone to follow. Aldric has known that for a year. He lays his palm flat against the oak.' },
    { kind: 'narrate', text: 'It opens on a sound like a breath drawn in. The stair beyond is black, and smells of oil and cold stone, and of something sweet beneath, like a sickroom where someone has been bringing flowers.' },
    { kind: 'narrate', text: 'Somewhere far above them, a pendulum swings once — and does not come back.' },
    { kind: 'line', who: 'teddy', text: 'Mind the stairs. They count.' },
  ],
};

const I1: Cinematic = {
  id: 'ch4_i1', name: 'Chapter IV · The Apprentice', bg: 'clocktower', tone: 'cold',
  clock: '22:58',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV · INTERLUDE', title: 'The Apprentice', sub: 'The winding room · step one hundred and forty' },
    { kind: 'narrate', text: 'At the hundred and fortieth step the stair opens into a small round room with a bench, a winding stand, and a window no wider than a letterbox. Below it Vellmoor lies in the fog like something under a sheet.' },
    { kind: 'narrate', text: 'Aldric sits down on the bench as though his knees have made the decision without him. He runs his thumb along a groove in the wood, worn there by a thumb — by this thumb — over twenty years.' },
    { kind: 'line', who: 'teddy', text: 'I used to eat my lunch here. Bread and dripping, and an apple in a good week. He would come up at one o’clock and pretend he had not come to check my winding.' },
    { kind: 'line', who: 'hesper', text: 'How did you come to him? You said eleven years old.' },
    { kind: 'line', who: 'teddy', text: 'I came to him through his shop window, Mr. Astrée. Elbow first. I was a thief. Not a good one.' },
    { kind: 'narrate', text: 'Spindle Street, 1909. Snow on the cobbles and the gas just lit. A shop with a bow window full of clocks, each set a second apart, so that on the hour the whole window chimes for a long, untidy minute, like a flock of birds settling.', bg: 'parlour', tone: 'warm' },
    { kind: 'narrate', text: 'Above the door, in gilt that has not yet had time to fade: A. VIRE · CLOCKMAKER. There is a space after it on the board, as if the signwriter had been asked to leave room.' },
    { kind: 'narrate', text: 'A boy with no coat puts his elbow through the corner pane at a quarter past six and closes his fist around a silver pocket watch. The shop door opens before he can run. He does not run. He has never seen so many clocks in his life, and every one of them is beginning to chime.' },
    { kind: 'line', who: 'Aldous Vire', text: 'That one is broken, you know. It loses four minutes a day. If you are going to steal a watch, steal one that works. It is a matter of professional pride — yours and mine both.' },
    { kind: 'line', who: 'Aldous Vire', text: 'What is wrong with it? Go on. You have it in your hand. Hold it to your ear and tell me what is wrong with it, and I shan’t call the constable.' },
    { kind: 'narrate', text: 'The boy listens. He has been told all his life that he is stupid, and he believes it, and so he listens very hard — because it is the first thing anyone has ever asked of him that he thinks he might not get wrong.' },
    { kind: 'line', who: 'Aldric, aged eleven', text: 'It… limps. Tick, tick — ti-tick. Like a horse with a stone in its shoe.' },
    { kind: 'narrate', text: 'Aldous Vire looks at him for a long time. Then he opens the door wider, letting the warm out into the snow, and says the thing that will decide the next twenty years of a life.' },
    { kind: 'line', who: 'Aldous Vire', text: 'The escapement is worn. Well heard. Come in and I shall show you why, and then you may sweep up the glass. You will call me Mr. Vire until you can true a balance wheel. After that you may call me what you like.' },
    { kind: 'bg', bg: 'clocktower', tone: 'cold' },
    { kind: 'line', who: 'teddy', text: 'I never called him anything but “sir.” Not because he asked it. Because I never got good enough at balance wheels to feel I had earned the rest.' },
    { kind: 'line', who: 'odile', text: 'And his wife? You would have known her.' },
    { kind: 'line', who: 'teddy', text: 'Hélène. She fed me. That is most of what I remember, and it is no small thing to remember about a person. Soup, and a voice in the back room singing something French, and the sound of her laughing at him when he swore at a mainspring.' },
    { kind: 'narrate', text: 'The third of March, 1919. A quarter to six in the morning. Aldric is twenty-one and asleep on the workshop floor with his head on a coil of brass wire, because no one has told him to go home, and he would not have gone.', bg: 'parlour', tone: 'warm' },
    { kind: 'narrate', text: 'A baby cries upstairs. Then, a long while after, the house goes very quiet, and the light under the shutters turns from grey to gold.' },
    { kind: 'narrate', text: 'At seven, Aldous Vire comes down the stairs with something wrapped in a blanket. He says nothing at all. He hands the bundle to Aldric the way one hands a man a tool, and goes to the window.' },
    { kind: 'narrate', text: 'He stops the clocks. All of them. One by one along the bow window he opens each case and lays a single finger on each pendulum, until the shop is so quiet Aldric can hear the baby breathing.' },
    { kind: 'line', who: 'wren', text: 'The old custom. When someone dies, you stop the clocks in the house.' },
    { kind: 'line', who: 'teddy', text: 'At six minutes past six. Forty-one clocks. He set every hand to the minute she went, and left them there.' },
    { kind: 'line', who: 'teddy', text: 'They stayed stopped nine days. Then Colette woke at four one morning wanting feeding, and he could not tell the hour, so he started the kitchen clock to know when. Then the next. By Easter they were all going.' },
    { kind: 'line', who: 'odile', text: 'So she started them. The first time.' },
    { kind: 'line', who: 'teddy', text: 'She was nine days old and she started forty-one clocks. He had the signwriter back that summer to fill in the space on the board.' },
    { kind: 'narrate', text: 'A. VIRE & DAUGHTER · CLOCKMAKERS.', bg: 'parlour', tone: 'warm' },
    { kind: 'bg', bg: 'clocktower', tone: 'cold' },
    { kind: 'line', who: 'bastian', text: 'He stopped the clocks after her mother died. And this time he stopped them before.' },
    { kind: 'line', who: 'teddy', text: 'Before. Yes. That is the whole of it, isn’t it. The whole of what he did, in one word.' },
    { kind: 'narrate', text: 'On the winding stand, held down by a blue oil tin, lies a folded square of paper. It has not yellowed; nothing up here has had time to yellow. On the outside is a single word in a small slanting hand: Aldric.' },
    { kind: 'line', who: 'teddy', text: '…That is his hand.' },
    { kind: 'line', who: 'wren', text: 'It’s addressed to you. Would you like me to—' },
    { kind: 'line', who: 'teddy', text: 'No. I can read. He taught me, at that bench, with the backs of old invoices. Give it here.' },
    { kind: 'letter', text: 'Aldric — The oil for the great wheel is in the blue tin, not the green. The green is for the carillon and will gum the train. Wind nothing tonight. If you are reading this then you did not go home, and I knew you would not, and I am sorry to have asked it of you.', sign: '— A.V.' },
    { kind: 'line', who: 'teddy', text: 'He knew I would come up. And he left me a note about oil.' },
    { kind: 'line', who: 'teddy', text: 'That was how he said everything that mattered. He would tell you which tin. If he loved you, you knew, because he told you which tin.' },
    { kind: 'line', who: 'hesper', text: 'For what it’s worth, my father said everything that mattered by complaining about the weather. You learn the dialect.' },
    { kind: 'narrate', text: 'Aldric folds the note in four and tucks it into his breast pocket, over the place where the key used to hang. Then he picks up the blue tin, and puts that in his pocket too.' },
    { kind: 'line', who: 'teddy', text: 'For the great wheel. When we get there. He would want it done properly.' },
    { kind: 'line', who: 'wren', text: 'You still mean to put the hands back.' },
    { kind: 'line', who: 'teddy', text: 'I do not ask to be forgiven, Keeper. I ask only to be the one who puts the hands back. It is a small thing to ask. I have asked it of nobody but the stairs.' },
    { kind: 'narrate', text: 'Above them something begins to sing the Gloria in a voice made of paper, and loses its place, and begins again. They climb towards it.' },
  ],
};

const I2: Cinematic = {
  id: 'ch4_i2', name: 'Chapter IV · Letters to Hélène', bg: 'clocktower', tone: 'cold',
  clock: '23:21',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV · INTERLUDE', title: 'Letters to Hélène', sub: 'The bell chamber' },
    { kind: 'narrate', text: 'The carillon hangs in the dark like a family of sleeping animals: twenty-three bells, great and small, every one still faintly humming the stroke that should not have been.' },
    { kind: 'narrate', text: 'Behind Great Margaret, in a hollow of the stone where the founders once kept their tallow, Elias finds a shortbread tin with a tartan lid, dented at one corner as though it had been dropped down a flight of stairs and forgiven.' },
    { kind: 'line', who: 'hesper', text: 'Letters. Dozens of them. Folded small, the way children fold things they mean to keep.' },
    { kind: 'line', who: 'wren', text: 'Addressed in pencil. “Mama. Care of the Sky.”' },
    { kind: 'line', who: 'teddy', text: 'She gave them to him to post. Once a month, from the time she could hold a pencil. He told her he carried them to the top of the tower, because it was the nearest place to the sky he had a key to.' },
    { kind: 'line', who: 'odile', text: 'And he never sent them.' },
    { kind: 'line', who: 'teddy', text: 'Where would he send them, Seraphine?' },
    { kind: 'line', who: 'wren', text: 'Here. He sent them here. This is as far as he could carry them.' },
    { kind: 'line', who: 'wren', text: 'I am a postman. I deliver letters, and a great many of them go to people who cannot answer. But a letter read aloud has been delivered. I have always believed that. …May I?' },
    { kind: 'line', who: 'teddy', text: 'She would have liked a postman. She was forever asking where letters went after the pillar box.' },
    { kind: 'narrate', text: 'Corvin sits down with his back to Great Margaret. The bell is cold through his coat. He sets the Lantern on the boards, and in its light the first letter opens like a hand.' },
    { kind: 'letter', text: 'Dear Mama, It is 1929 now. Papa let me stay up and we heard his clock strike midnight from the window. He says it is the best clock in the world. I asked what the second best was and he said there isn’t one, only a great many worse ones. I think that is boasting.', sign: '— Colette, January' },
    { kind: 'line', who: 'bastian', text: 'It is boasting. He knew it was. He liked being caught at it.' },
    { kind: 'letter', text: 'Dear Mama, I am ten! Papa took me to the Gloaming, row K. Gloria Ambre sang and I counted her hair-pins — thirty-one, a new record. Papa cried at the sad part and said it was the dust. There is no dust in the Gloaming. The Count has it swept every day. I checked.', sign: '— Colette, March' },
    { kind: 'line', who: 'bastian', text: 'Thirty-one. I told you. I told you.' },
    { kind: 'letter', text: 'Dear Mama, Dr. Halloway came again. He has cold hands and a kind moustache. I cannot do the stairs now, so Papa built a lift in the stairwell with weights and a little bell. It rings when I arrive. I arrive about eleven times a day, mostly for the bell.', sign: '— Colette, May' },
    { kind: 'line', who: 'teddy', text: 'I helped him build it. Three nights; he did not sleep. He kept saying, “If she cannot climb the stairs, the stairs will have to climb her.” I thought he meant the lift.' },
    { kind: 'line', who: 'odile', text: 'He did not mean the lift.' },
    { kind: 'line', who: 'teddy', text: 'No. I see that now. He meant this. All of this.' },
    { kind: 'letter', text: 'Dear Mama, On Thursdays a lady comes to the ward at St. Brigid’s with doves in a gold cage, and lets us name them. I named one Captain Biscuit. Everyone said a dove can’t be a captain. The lady said a dove can be anything it is named. I like her very much.', sign: '— Colette, July' },
    { kind: 'line', who: 'hesper', text: 'Aveline. That is Aveline, down at the west door, keeping the doves for us.' },
    { kind: 'letter', text: 'Dear Mama, There are crows on my windowsill. I give them the crusts Mrs. Pruitt cuts off. One is very old with a white feather on his wing, like a pen behind an ear. I call him the Postmaster. He looks at me as though I owe him a stamp.', sign: '— Colette, September' },
    { kind: 'line', who: 'wren', text: '…Sexton.' },
    { kind: 'line', who: 'odile', text: 'Your crow?' },
    { kind: 'line', who: 'wren', text: 'My oldest. White feather on the left wing. Every autumn he goes off alone and comes home fat and pleased with himself. I always wondered where. The Postmaster. She was not far wrong.' },
    { kind: 'letter', text: 'Dear Mama, Papa is making a doll with my face. I told him to make her braver than me, and give her a red dress, because I have been in white nightgowns all year and somebody in this family ought to wear red. He laughed. He hasn’t laughed since summer. So I shall keep asking for things.', sign: '— Colette, November' },
    { kind: 'narrate', text: 'Nobody looks at Columbine. Everybody is very careful not to look at Columbine. She stands among the bells with her hands folded over her red silk, and she does not move at all.' },
    { kind: 'line', who: 'bastian', text: 'Go on. Please. Don’t stop on my account. I want to know what she asked for next.' },
    { kind: 'letter', text: 'Dear Mama, I don’t think I will write to you in January. I think I might see you instead. I’m not frightened. I only want to ask: what does the morning look like? Papa always draws the curtains. I have never seen a sunrise. He says they are overrated, like oysters.', sign: '— Colette, December' },
    { kind: 'narrate', text: 'For a long while nobody speaks. Somewhere below, the great wheel strains against the fireflies in its teeth, and a bell answers it with a sound too low to be a note.' },
    { kind: 'line', who: 'teddy', text: 'Ten years. She never saw one. He drew the curtains every morning of her life, and children sleep through the dawn in any case, and so nobody thought — I never once thought—' },
    { kind: 'line', who: 'odile', text: 'She thought. She thought about it every month, and wrote it down, and gave it to him to post.' },
    { kind: 'line', who: 'ichabod', text: 'In the harbour we used to say the sea forgives everything except being kept from the moon. I suppose children are the same about the morning.' },
    { kind: 'narrate', text: 'Corvin folds the last letter along its old creases, lays it with the others, and closes the tin with great care — the way one closes a door on a sleeping child.' },
    { kind: 'line', who: 'wren', text: 'Delivered. Every one of them. Somebody read them. That counts.' },
    { kind: 'line', who: 'bastian', text: 'Corvin. When we find him… may I carry the tin?' },
    { kind: 'line', who: 'wren', text: 'It’s yours to carry. I think it always was.' },
    { kind: 'narrate', text: 'Columbine holds the tin against her chest, where a heart would be if anyone had thought to give her one. On Elias’s map the gold thread burns a little brighter. For the first time tonight, the stairs seem to want to be climbed.' },
  ],
};

const I3: Cinematic = {
  id: 'ch4_i3', name: 'Chapter IV · The City Below', bg: 'street', tone: 'cold',
  clock: '23:40',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV · INTERLUDE', title: 'The City Below', sub: 'Spindle Street · the harbour · the nave' },
    { kind: 'narrate', text: 'Far below the clock, on Spindle Street, a lamplighter has been walking his round for a year with an unlit pole.' },
    { kind: 'narrate', text: 'He is called Fennick. He has forgotten that. He has not forgotten the round: thirty-eight lamps from the bridge to the clockmaker’s and back, each with a name painted small on its brass collar, the way Vellmoor has always named its lamps.' },
    { kind: 'line', who: 'Old Fennick', text: 'Evening, Bartholomew. Evening, Marguerite. Evening, Old Tom — mind your glass, it’s cracked. …Evening, Constance.' },
    { kind: 'narrate', text: 'Constance stands on the corner outside No. 9, where the clockmaker’s bow window has been dark for a year. She has been dark for a year too. Fennick lifts his pole to her out of habit, as he does every night, without hope.' },
    { kind: 'narrate', text: 'High above, in the belly of the clock, a spring as long as a street sighs open by a single turn. Constance coughs — there is no other word for it — and catches, and burns.' },
    { kind: 'line', who: 'Old Fennick', text: '…Constance? Constance! There’s my girl. Oh, there’s my good, good girl.' },
    { kind: 'narrate', text: 'In her light the shop sign comes back, letter by letter, like a name remembered on the tip of the tongue. A. VIRE — & — DAUGHTER.' },
    { kind: 'narrate', text: 'An upstairs curtain moves at No. 9. A woman in a dressing gown and a hairnet puts her head out of the window with the face of someone who has been asleep on her feet for a year and would like an explanation.' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'Mr. Fennick? Is that you making that racket? It is the middle of the — it is — what time is it?' },
    { kind: 'line', who: 'Old Fennick', text: 'Don’t know, Mrs. Pruitt. Don’t rightly know my own name. But Constance is lit, and that’s a start.' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'Pruitt. Yes. I keep house for Mr. Vire. Kept. Keep. There’s a child — there was a child, in the back bedroom. Colette. Colette. Oh, Lord. Where has he taken her?' },
    { kind: 'narrate', text: 'She remembers. The Dimming had folded that evening up and put it away in a drawer, and the light of a single lamp has pulled the drawer open.' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'Ten o’clock. She asked me for writing paper and an envelope — the good paper. She sealed it with candle-wax and her mother’s old thimble, because she had no seal, and she said, “Open the window, Mrs. Pruitt. The Postmaster’s here.”' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'There was a crow on the sill. An old one, white feather in his wing. She held the letter out and he took it in his beak as neat as a bank clerk, and off he went over the roofs towards Corvid Lane.' },
    { kind: 'line', who: 'Old Fennick', text: 'Who was it to, then?' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'She wouldn’t say. Only that it was for “whoever stops the clock.” I thought it was one of her games. Then Mr. Vire came in with the blue blanket and said they were off to see the fireworks.' },
    { kind: 'line', who: 'Mrs. Pruitt', text: 'And I knew there weren’t going to be any fireworks, Mr. Fennick, and I let him go. Everybody let him go. That’s the part nobody will want to say, after. We all of us let him.' },
    { kind: 'narrate', text: 'At the harbour, every masthead lantern in the anchorage flickers once, like a row of eyelids, and goes out again. Not yet, it seems to say. But soon.', bg: 'docks', tone: 'cold' },
    { kind: 'line', who: 'Harbourmaster Marée', text: 'Did you see that? Up on the tower — that’s Lucien. That’s my boy up there, doing that. I’d know his hand on a tide anywhere, and that was a tide of a kind.' },
    { kind: 'narrate', text: 'In the nave of St. Aldhelm’s the candles burn all the way to the altar now, and there are people in the pews. A dozen, no more. They drifted in out of the fog the way moths come to a window, and sat down, and found they could remember the words to the hymns.', bg: 'clocktower', tone: 'warm' },
    { kind: 'line', who: 'Verger Abney', text: 'Evensong. Of a sort. I shan’t pass the plate. It does not seem the night for it.' },
    { kind: 'line', who: 'marigold', text: 'Put me down for a guinea in any case, Abney. I have never yet attended a performance I did not pay for, and I do not intend to begin in a cathedral.' },
    { kind: 'line', who: 'augustin', text: 'Your name, madam? And yours, sir? I am writing them down, in the margin. Next to the jam roly-poly, I am afraid. It is the only margin I have left.' },
    { kind: 'line', who: 'A woman in the pews', text: 'Greaves. Martha Greaves. I — thank you. I didn’t know I’d lost it till you asked.' },
    { kind: 'line', who: 'kit', text: 'The orrery has quickened. Can you hear it? Something up there has given the city back a turn of the key.' },
    { kind: 'line', who: 'evangeline', text: 'The doves are awake. Hortensia keeps looking at the tower door. She has not looked at anything in a year.' },
    { kind: 'line', who: 'marigold', text: 'Then my candles are steady. Abney, the light at the foot of the stairs is yours. Mind it as you would a leading lady: never let it see you are worried.' },
    { kind: 'line', who: 'Verger Abney', text: 'And where are you going, my lord?' },
    { kind: 'line', who: 'marigold', text: 'Up. I have sat in the stalls for a year. I find I should like, just once, to be on the stage when the curtain rises.' },
    { kind: 'narrate', text: 'He leaves a rose from his buttonhole on the font beside Isidore’s cookery book, for luck. Then the Crimson Patron goes through the tower door with his cane under his arm, taking the stairs two at a time in a manner his physician would deplore.' },
    { kind: 'narrate', text: 'And on the cathedral roof, where no crow has roosted for a year, there is a crow. One. Old, with a white feather on his left wing.', bg: 'street', tone: 'cold' },
    { kind: 'narrate', text: 'He sits on the stone gutter above the north face, directly over the blank clock, and does what crows almost never do. He waits.' },
    { kind: 'narrate', text: 'By the time the mainspring has finished its sigh there are forty crows on the roof. By the time Valerian reaches the hundredth step there are two hundred. They do not call. They line the cornices like mourners at a gate, every head turned to the same dark glass.' },
    { kind: 'narrate', text: 'Inside the clock, Corvin feels his satchel grow warm against his side — as though the letter in it had heard itself spoken of, somewhere far below.', bg: 'clocktower', tone: 'cold' },
  ],
};

const I4: Cinematic = {
  id: 'ch4_i4', name: 'Chapter IV · The Doll’s Commission', bg: 'clocktower', tone: 'cold',
  clock: '23:52',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV · INTERLUDE', title: 'The Doll’s Commission', sub: 'The Gallery of Faces' },
    { kind: 'narrate', text: 'The others go on to scout the next stair. Columbine stays in the gallery. Corvin stays with her — because somebody should, and because he has spent a year learning the difference between a person who wants to be alone and one who only wants not to be spoken to.' },
    { kind: 'narrate', text: 'Three hundred painted faces look down on them. Three hundred sleeping girls, wreathed in numerals, stopped at three hundred different wrong times.' },
    { kind: 'line', who: 'bastian', text: 'Do you know what I keep thinking? She was ten. Ten years old, and dying, and she asked for a doll in a red dress. Not a cure. Not a pony. A doll. What sort of person asks for that?' },
    { kind: 'line', who: 'wren', text: 'The sort who knew a pony would go to waste.' },
    { kind: 'line', who: 'bastian', text: 'That’s horrible.' },
    { kind: 'line', who: 'wren', text: 'It is. It is also very brave, and very practical. She sounds like a practical girl.' },
    { kind: 'line', who: 'bastian', text: 'She was. She is. I— Corvin, there is a bubble coming up. A big one. I can feel it in every joint. Will you stay?' },
    { kind: 'line', who: 'wren', text: 'I am not going anywhere.' },
    { kind: 'narrate', text: 'Spindle Street, November 1929. The back room of the shop, curtains open, because it is afternoon and afternoons are allowed. A fire. A workbench. On the bench, a figure of pale wood and unpainted porcelain, as tall as a girl of ten.', bg: 'parlour', tone: 'warm' },
    { kind: 'narrate', text: 'In a wheeled chair by the fire, wrapped in a blue blanket with white stars stitched around the hem, sits a girl of ten. She is the same height as the doll — or would be, if she could stand.' },
    { kind: 'line', who: 'Colette', text: 'Her nose is wrong.' },
    { kind: 'line', who: 'Aldous Vire', text: 'Her nose is your nose. I measured it. Twice. With calipers. You complained.' },
    { kind: 'line', who: 'Colette', text: 'Then give her a better nose. She needn’t have all my bits, Papa. Only the good ones. And she’s to be braver than me. Write that down.' },
    { kind: 'line', who: 'Aldous Vire', text: 'You are the bravest person I know. I should not know how to make anything braver.' },
    { kind: 'line', who: 'Colette', text: 'Then make her braver than you. That’s easy.' },
    { kind: 'narrate', text: 'He laughs. It is not a large laugh — it has been a long year — but it takes him by surprise, and he writes the word down as instructed, on the back of an invoice: Braver.' },
    { kind: 'line', who: 'Colette', text: 'A red dress. Not pink. Not rose. Red, like a pillar box. And give her your eyes.' },
    { kind: 'line', who: 'Aldous Vire', text: 'My eyes are grey and tired, little one. You can do better than my eyes.' },
    { kind: 'line', who: 'Colette', text: 'Give her them anyway. Then she’ll look at things the way you do. And when she looks at me, I’ll know what you see.' },
    { kind: 'narrate', text: 'He does not answer that. He takes up the finest brush on the bench, mixes a grey that is exactly the colour of his own eyes in a shaving mirror at five in the morning, and begins.' },
    { kind: 'line', who: 'Colette', text: 'And don’t give her my cough.' },
    { kind: 'line', who: 'Aldous Vire', text: 'I would not give anyone your cough. I would not give your cough to the tax inspector.' },
    { kind: 'line', who: 'Colette', text: 'What shall we call her?' },
    { kind: 'line', who: 'Aldous Vire', text: 'I had rather thought—' },
    { kind: 'line', who: 'Colette', text: 'Not Colette. One of me is plenty. Call her Columbine, like in the harlequinade. Columbine always gets away in the end. Harlequin never quite catches her.' },
    { kind: 'line', who: 'Aldous Vire', text: 'Columbine. Very well. Columbine Rouge, for the dress.' },
    { kind: 'line', who: 'Colette', text: 'And Papa — sign her. All over, every joint. So if she ever gets lost, people will know who to bring her back to.' },
    { kind: 'narrate', text: 'He signs her. Every joint, on the inside, where the silk will cover it, in brass letters so small he needs a jeweller’s loupe: A.V. A.V. A.V. Forty-one times. He does not notice the number. Colette does, and says nothing, and smiles at the fire.' },
    { kind: 'line', who: 'Colette', text: 'One more thing. When I’m gone — no, listen, Papa, listen to me — when I’m gone, cut her strings. She shouldn’t have to dance for nobody.' },
    { kind: 'line', who: 'Aldous Vire', text: 'Colette.' },
    { kind: 'line', who: 'Colette', text: 'Promise.' },
    { kind: 'narrate', text: 'He promises. He is a man who keeps his promises the way he keeps his clocks: exactly, and on time. It is the only one he will ever break.' },
    { kind: 'narrate', text: 'The thirty-first of December, a quarter to eleven at night. The doll stands by the bed in a dress like a pillar box, and the clockmaker kneels to wind the key in her back. His hands shake so badly that he drops it twice.' },
    { kind: 'line', who: 'Aldous Vire', text: 'Dance until morning, Colette.' },
    { kind: 'narrate', text: 'He says it to the doll. For a week he has not been able to say that name to his daughter without his voice doing something that frightens her. So he says it to the one who cannot be frightened.' },
    { kind: 'bg', bg: 'clocktower', tone: 'cold' },
    { kind: 'line', who: 'bastian', text: 'He called me by her name because he couldn’t say it to her any more.' },
    { kind: 'line', who: 'wren', text: 'Yes.' },
    { kind: 'line', who: 'bastian', text: 'And she gave me mine so I would never have to be her. She did it on purpose, Corvin. A ten-year-old girl, dying, and she stopped to think: the doll will need a name of her own.' },
    { kind: 'line', who: 'bastian', text: 'I have been Columbine since Corvid Lane. I thought the name was the first thing I ever owned. …It was. She only gave it to me first.' },
    { kind: 'line', who: 'bastian', text: 'And the strings. He promised to cut them. He didn’t, did he? He couldn’t. He wound me, and went up the tower with her, and left them on.' },
    { kind: 'line', who: 'wren', text: 'They were cut when you woke.' },
    { kind: 'line', who: 'bastian', text: 'At the thirteenth stroke. Clean through, all at once, like scissors. If he didn’t do it… then who did?' },
    { kind: 'narrate', text: 'Corvin has no answer. Neither, painted three hundred times in the dark above them, has the sleeping girl.' },
    { kind: 'line', who: 'bastian', text: 'I’m not a copy, am I. I was never meant to replace her. I was meant to be the one who gets away.' },
    { kind: 'line', who: 'wren', text: 'Then get away. Up those stairs and out the other side, into the morning. That is an order from a postman. Postmen are not permitted to give orders, so you may take it that it’s important.' },
    { kind: 'narrate', text: 'Columbine laughs — a small, cracked, porcelain laugh — and wipes her eyes, though she has never in her life shed a tear and does not now. Then she takes up the tartan tin, tucks it under her arm, and goes to the stairs.' },
  ],
};

const I5: Cinematic = {
  id: 'ch4_i5', name: 'Chapter IV · The Last Game', bg: 'clocktower', tone: 'cold',
  clock: '23:59',
  shots: [
    { kind: 'title', kicker: 'CHAPTER IV · INTERLUDE', title: 'The Last Game', sub: 'Behind the clock face' },
    { kind: 'narrate', text: 'Behind the clock face, where the frozen city’s light comes in backwards through the numerals, a countess sits at a small table with a chessboard, and waits.' },
    { kind: 'narrate', text: 'She has been waiting since the year stopped. She has not minded much. Ophelia Sablier has waited for things in her life that would make a year look like a luncheon.' },
    { kind: 'narrate', text: 'Across the room, on a throne built of hour hands — hundreds of them, gilt and iron and silver, from every clock its maker ever made — sits the Hourless King. Beside the throne, a small bed. In the bed, a girl. Above the girl, a fall of dust that has not fallen.' },
    { kind: 'line', who: 'hourless', text: 'Another game, Countess?' },
    { kind: 'line', who: 'ottoline', text: 'For what stake, Aldous? You have taken everything in this city that could be wagered. You even took my minute.' },
    { kind: 'line', who: 'hourless', text: 'I won your minute.' },
    { kind: 'line', who: 'ottoline', text: 'You did. I have asked myself every day since whether I let you. I have never lost a game I did not choose to lose. And yet I cannot, for the life of me, remember choosing.' },
    { kind: 'narrate', text: 'The thirty-first of December, half past eleven. The same room, warmer then. Coals in a brazier. The girl in the bed, asleep and breathing. And a man in his shirtsleeves setting out the pieces with hands that will not quite keep still.', tone: 'warm' },
    { kind: 'line', who: 'Aldous Vire', text: 'Thank you for coming, Countess. I could not think whom else to ask. A woman who collects seconds ought to be present for the last one.' },
    { kind: 'line', who: 'ottoline', text: 'You sent a card, darling. “A game, at the top of the Cathedral. Stake: one minute. Bring your glass.” I never refuse a card with a stake on it. What on earth do you want with a minute?' },
    { kind: 'line', who: 'Aldous Vire', text: 'Only the one. The last of the year. I mean to keep it.' },
    { kind: 'line', who: 'ottoline', text: 'Keep it?' },
    { kind: 'line', who: 'Aldous Vire', text: 'A minute is a mechanism like any other. Its escapement is the second. Jam the second, and the minute cannot end. I have built the jam. I need only a minute to put it in.' },
    { kind: 'narrate', text: 'They play. He plays the way he builds — patiently, precisely, every move a tooth meeting a tooth. She plays the way she lives, as though she has all the time in the world. She does. That has always been the trouble.' },
    { kind: 'narrate', text: 'At eleven fifty-eight she looks down and finds her king in a corner, behind a wall of his own pawns, with nowhere to go and nobody coming for him.' },
    { kind: 'line', who: 'ottoline', text: 'Oh. Oh, that is a pretty mate. Wherever did you learn it?' },
    { kind: 'line', who: 'Aldous Vire', text: 'My wife. She played on the train to the seaside, the summer we were married. She never let me win either.' },
    { kind: 'line', who: 'ottoline', text: 'I did not let you win.' },
    { kind: 'line', who: 'Aldous Vire', text: '…Didn’t you?' },
    { kind: 'narrate', text: 'She tips her hourglass, and a minute’s sand — sixty grains; she has counted them; she counts everything — slides into the palm of his hand. He closes his fingers over it. Then he rises, and goes to the bell ropes.' },
    { kind: 'narrate', text: 'And she watches. She watches the whole of it. She is the only person in Vellmoor who does.' },
    { kind: 'narrate', text: 'Now. The coals are long cold. The girl has not finished her breath. And the man on the throne has become something that is not quite a man any longer.', tone: 'cold' },
    { kind: 'line', who: 'hourless', text: 'You might have stopped me, Ophelia. You knew what I meant to do. You might have kept your minute.' },
    { kind: 'line', who: 'ottoline', text: 'I might. But I have spent a very long life watching people squander their seconds, darling, and you were the first in a century who wanted one for love. I was curious to see what you would do with it.' },
    { kind: 'line', who: 'hourless', text: 'And now?' },
    { kind: 'line', who: 'ottoline', text: 'Now I think you have done everything with it that can be done. It has gone stale. It is time it was spent.' },
    { kind: 'line', who: 'hourless', text: 'They are coming. I can hear them on the stairs. Aldric is with them. Aldric, of all people.' },
    { kind: 'line', who: 'ottoline', text: 'Aldric especially. He is the only one of us you never had to ask.' },
    { kind: 'narrate', text: 'There is one more thing she saw that night. She has not told him. She has told no one. She is waiting for the right moment — and she, of all people, knows exactly when that is.' },
    { kind: 'narrate', text: 'It is not yet.' },
    { kind: 'line', who: 'ottoline', text: 'I shall set the pieces up again, Aldous. Not for us. For them. White to move.' },
    { kind: 'line', who: 'hourless', text: 'They will lose.' },
    { kind: 'line', who: 'ottoline', text: 'Everyone loses, darling. The only question has ever been what, and when. — Ah. Footsteps on the ladder. The four hundred and thirteenth step. Everybody forgets the ladder.' },
    { kind: 'narrate', text: 'She lays her hourglass on its side so that nothing in it can fall, smooths her skirts, and composes her face into the expression of a woman who has been kept waiting and intends to mention it.' },
  ],
};

const END: Cinematic = {
  id: 'ch4_end', name: 'Chapter IV · Let the Morning Come', bg: 'clocktower', tone: 'cold',
  clock: '05:59',
  shots: [
    { kind: 'narrate', text: 'The Hourless King kneels among the broken hour hands. Beside him, in a small bed, Colette sleeps — pale and peaceful, exactly as she was at one minute to midnight.' },
    { kind: 'narrate', text: 'The Dimming comes off him in strips, like wet paper off a wall. Underneath is a thin man of fifty-six in his shirtsleeves, with oil in the creases of his knuckles and an old soldering burn on his left thumb, who has not slept in a year and looks it.' },
    { kind: 'narrate', text: 'Around him the throne has come down in a long bright landslide: gilt hands, iron hands, the delicate blued-steel hands of ladies’ watches, the fat brass hands of kitchen clocks. Every hand Aldous Vire ever cut, lying in a drift like autumn leaves.' },
    { kind: 'narrate', text: 'Through the great glass of the clock face the city lies laid out backwards, a board at the end of a game. And in the bed a girl of ten, in a blue blanket with white stars around its hem, has been halfway through one breath for a year.' },
    { kind: 'line', who: 'hourless', text: 'Don’t. Don’t come any nearer to her. You’ve won. Take your lantern and your crows and go and light whatever you like. Only leave us this one minute.' },
    { kind: 'line', who: 'wren', text: 'It isn’t one minute, Aldous. It’s a year. It is every minute of everyone in the city, all piled up in one room.' },
    { kind: 'line', who: 'hourless', text: 'I know what it is. I built it. Do you think I don’t hear them? Every lamp, every name — I hear them in the spring all night long. It is the loudest silence ever made.' },
    { kind: 'line', who: 'hourless', text: 'And I would do it again. I would do it every night for a thousand years, if it meant she never had to breathe out.' },
    { kind: 'line', who: 'odile', text: 'Look at her, Aldous. She has been halfway through one breath since midnight. That is not living. It is a held breath, and she is tired of holding it.' },
    { kind: 'line', who: 'hourless', text: 'Halfway is more than nothing.' },
    { kind: 'line', who: 'teddy', text: 'Master.' },
    { kind: 'line', who: 'hourless', text: 'Aldric. You came up. You actually came up. Twenty years, and you never once disobeyed me, and you choose tonight.' },
    { kind: 'line', who: 'teddy', text: 'You told me to go home to my mother, sir. My mother is dead. You held my hat at her funeral. I knew then that you were not well, and I let you up the stairs anyway, because I wanted the fireworks to be true.' },
    { kind: 'line', who: 'teddy', text: 'I have stood at the bottom of those stairs for a year being sorry. I am done being sorry at the bottom. I should like to be sorry up here, where it might be of some use.' },
    { kind: 'line', who: 'hourless', text: 'You should have refused me.' },
    { kind: 'line', who: 'teddy', text: 'Yes.' },
    { kind: 'line', who: 'hourless', text: '…You always were a dreadful liar. Even about small things. Twenty years, and you never once told me my soldering was good.' },
    { kind: 'line', who: 'teddy', text: 'It wasn’t.' },
    { kind: 'narrate', text: 'Columbine has not moved since the King fell. She stands at the foot of the bed with the tartan tin held against her, very straight, the way a doll stands when nobody has told it what to do.' },
    { kind: 'line', who: 'bastian', text: 'She’s smaller than I thought.' },
    { kind: 'line', who: 'hourless', text: 'She was always small. Small for her age. The doctor said her heart was too large for her and too slow — that it ran like a clock with a weak spring, losing a little every day, and nothing would wind it.' },
    { kind: 'line', who: 'hourless', text: 'I am a clockmaker. I have opened ten thousand mechanisms in my life. I could not open that one. Do you understand? The one mechanism in the world that mattered, and they would not let me so much as look.' },
    { kind: 'line', who: 'bastian', text: 'So you stopped all the others instead.' },
    { kind: 'line', who: 'hourless', text: 'Yes.' },
    { kind: 'line', who: 'bastian', text: 'You made me to dance for her. I remember. Not being made — but dancing. Here, by this bed, every night. You worked the strings and hummed the Gloaming waltz, and she laughed until she coughed, and then she laughed again.' },
    { kind: 'line', who: 'hourless', text: 'You remember that?' },
    { kind: 'line', who: 'bastian', text: 'She told me everything. Every night, after you fell asleep in the chair. She talked to me for hours, because I was the only one in the room who wasn’t frightened. I listened. I didn’t know I was listening. I know now.' },
    { kind: 'line', who: 'hourless', text: 'And on the last night I wound you, and I said—' },
    { kind: 'line', who: 'bastian', text: '“Dance until morning, Colette.” You called me by her name.' },
    { kind: 'line', who: 'hourless', text: 'I could not say it to her any more. It hurt her, how I said it. So I said it to you.' },
    { kind: 'line', who: 'bastian', text: 'My name is Columbine. She gave it to me. You should know she did it on purpose. She said one of her was plenty.' },
    { kind: 'line', who: 'hourless', text: '…Yes. Yes, she did say that. She said it exactly like that.' },
    { kind: 'narrate', text: 'Something happens to Aldous Vire’s face then. It is not a smile. It is the place a smile would go, if he could only remember the way.' },
    { kind: 'line', who: 'odile', text: 'Keeper. There is something I must say. I have put it off for a year, and there is no more year left to put it off in.' },
    { kind: 'line', who: 'wren', text: 'The future you would not speak of.' },
    { kind: 'line', who: 'odile', text: 'The night I found you, I read the sky one last time before it froze. It said: the morning comes. Not for everyone. One light burning tonight will not be burning when the sun is up.' },
    { kind: 'line', who: 'odile', text: 'I did not know whose. I looked at your lantern and feared it was yours. I looked at Columbine and feared it was hers. I looked in my own glass and was — I confess it — a little relieved, and then ashamed of the relief.' },
    { kind: 'line', who: 'odile', text: 'It was never any of us. It was her. It has always been her. The stars knew it before her father did, and they were kinder about it than I have been.' },
    { kind: 'line', who: 'hourless', text: 'Then you knew. You climbed all this way knowing, and you still mean to bring the sun up.' },
    { kind: 'line', who: 'odile', text: 'Yes. Because the alternative is not that she lives, Aldous. The alternative is that nobody does.' },
    { kind: 'narrate', text: 'Corvin takes the envelope from his satchel. In the lantern-light the cream paper is almost gold. To whoever stops the clock.' },
    { kind: 'line', who: 'wren', text: 'Aldous. A crow brought me this a year ago. It was addressed “to whoever stops the clock.” I never opened it. I think it was meant for you.' },
    { kind: 'narrate', text: 'It came in the first minutes after the thirteenth stroke — not by the mail, but by Sexton, the oldest of his crows, who had spent all autumn eating crusts on a sickroom windowsill on Spindle Street, and knew exactly whose it was, and whom to take it to.' },
    { kind: 'line', who: 'hourless', text: 'I can’t. Look at my hands. I could not hold a screwdriver. I cannot hold a letter.' },
    { kind: 'line', who: 'wren', text: 'Then let me read it to you. That is what I do. A letter read aloud has been delivered.' },
    { kind: 'narrate', text: 'He breaks the seal. It is ordinary candle-wax, pressed with the end of a thimble because a ten-year-old girl had no seal of her own. Inside there are two sheets, folded small, the way children fold things they mean to keep.' },
    { kind: 'letter', text: 'To whoever stops the clock — If you are reading this, Papa has done something big and silly, because he always does when he is frightened. Please be gentle with him. He is very good at fixing things, and very bad at the things that can’t be fixed. Please give him the other page.', sign: '— C.V.' },
    { kind: 'line', who: 'wren', text: 'There’s a second page. It’s for you.' },
    { kind: 'letter', text: 'Papa — I heard you talking to the doctor. Please don’t be sad. I am not afraid of the morning. Let it come, and I will watch it with you, I promise. And Papa… let someone else dance now.', sign: '— Colette Vire, 31 December 1929' },
    { kind: 'letter', text: 'P.S. I have never seen a sunrise. Mrs. Pruitt says they are mostly orange. I would like to see one, please, with you, and not be told it is overrated. P.P.S. Columbine may keep the red dress.', sign: '— C.' },
    { kind: 'letter', text: 'P.P.P.S. On the back is PROJECT FIREFLY. It is my plan, and it is top secret. Mrs. Pruitt says every time somebody is forgotten a firefly goes up, so I am going to catch them all in a jar and keep them safe until the morning can find them. If I can’t finish it, whoever stops the clock has to. That is the rule.', sign: '— C.V., Head of Project Firefly' },
    { kind: 'line', who: 'wren', text: 'Project Firefly. …A year I have carried out her plan, lamp by lamp, and I never knew whose plan it was.' },
    { kind: 'line', who: 'bastian', text: 'The lantern. Every light we caught. It was her jar all along.' },
    { kind: 'line', who: 'hourless', text: 'She wrote this before midnight. She knew. She knew, and I… I stopped the whole world so that I would never have to read it.' },
    { kind: 'narrate', text: 'For a while there is no sound in the clock but the dust not falling. Then, a long way below, through four hundred and thirteen steps of stone, the sound of the verger’s congregation singing something, very badly, in the nave.' },
    { kind: 'line', who: 'hourless', text: 'I never let her see one. Ten years. I drew the curtains at five every morning of her life. Her mother died at sunrise, and I could not — I could not bear to have it in the house.' },
    { kind: 'line', who: 'hourless', text: 'Her mother said, “Oh. Look. It came.” And then she was gone. I have spent ten years making certain I would never hear those words again.' },
    { kind: 'line', who: 'wren', text: 'She is asking you to let her hear them.' },
    { kind: 'line', who: 'hourless', text: '“Let someone else dance now.”' },
    { kind: 'line', who: 'bastian', text: 'She meant me. Didn’t she.' },
    { kind: 'line', who: 'hourless', text: 'She meant you. She meant — let it be the turn of somebody who has a turn coming.' },
    { kind: 'line', who: 'ottoline', text: 'Aldous. Darling. I believe you owe me a minute.' },
    { kind: 'line', who: 'hourless', text: 'I won it from you. Fairly.' },
    { kind: 'line', who: 'ottoline', text: 'You won it. Whether fairly, I have wondered all year, and it no longer matters. You have kept it long enough. It has gone stale. Give it back, and I shall do you the kindness of spending it properly.' },
    { kind: 'narrate', text: 'She holds out the hourglass. In its upper bulb a minute of sand sits on the narrow neck of the glass like passengers on a platform, waiting for a train that was cancelled a year ago.' },
    { kind: 'line', who: 'hourless', text: 'If I give it back, the minute ends.' },
    { kind: 'line', who: 'ottoline', text: 'Minutes do. It is the one thing that can be said in their favour.' },
    { kind: 'line', who: 'teddy', text: 'Master. The hands. Let me put them back.' },
    { kind: 'narrate', text: 'For a long time Aldous Vire looks at the man he found in his shop window with a stolen watch in his fist. Then he looks at the drift of hands around his knees. Then, at last, at the bed.' },
    { kind: 'line', who: 'hourless', text: 'They are at the bottom. The long one with the gilt fleur at the tip. You regilded it yourself in ’24, and got leaf all over your eyebrows, and would not let anybody laugh.' },
    { kind: 'line', who: 'teddy', text: 'I remember.' },
    { kind: 'line', who: 'hourless', text: '…Go on, then. Go on, Aldric. I cannot do it. I should like very much for it to be done by someone who loves it.' },
    { kind: 'narrate', text: 'Aldric wades into the drift of hands the way a man wades into a river he swam in as a boy — knowing every stone. From the very bottom he draws out two hands of black iron, longer than he is tall, and shoulders them like a pair of oars.' },
    { kind: 'narrate', text: 'Behind the clock face there is a hatch to the arbor. He has opened it every Sunday for twenty years. It still sticks in the same place, and he still swears at it in the same word — and somehow that, of everything tonight, is what makes Lucien laugh aloud.' },
    { kind: 'line', who: 'ichabod', text: 'Sorry. Sorry. It’s only — the sea’s moving. Can you feel it? Under the floor, all the way up from the harbour. It knows.' },
    { kind: 'line', who: 'hesper', text: 'My map. Look at it. The gold thread is running off the edge of the page, into the margin. It’s drawing the morning. I never had the ink for that.' },
    { kind: 'line', who: 'marigold', text: 'Whatever you are all about to do, I beg you, do it before I find a chair. I am too old to witness history standing up, and too vain to witness it sitting down.' },
    { kind: 'line', who: 'bastian', text: 'Aldous. Will you hum it? The waltz. Only once. I should like to dance while he works. I don’t want her to wake to a quiet room.' },
    { kind: 'line', who: 'hourless', text: 'I haven’t the voice. I never had.' },
    { kind: 'line', who: 'bastian', text: 'You never did. She told me. She said it was the worst humming in Vellmoor, and the only humming she wanted.' },
    { kind: 'narrate', text: 'And Aldous Vire hums. It is a thin, cracked, tuneless sound, the hum of a man who has been not-weeping for a year and has forgotten which muscles are for which. It is, recognisably, the Gloaming waltz.' },
    { kind: 'narrate', text: 'Columbine dances. No strings now; no hands above her. She waltzes across a floor of fallen hours — one, two, three; one, two, three — and every time she turns she passes the bed, and every time she passes it she looks.' },
    { kind: 'line', who: 'marigold', text: 'The orchestra played that waltz at every gala for thirty years. I had quite decided nobody would ever dance it as well as Gloria sang it. How pleasant, at my age, to be wrong.' },
    { kind: 'narrate', text: 'Ophelia turns the hourglass over. The minute begins to fall.' },
    { kind: 'narrate', text: 'At the twentieth second, the pigeon that has hung in the bell chamber for a year finishes leaving, and is gone through the louvres in a clap of grey.' },
    { kind: 'narrate', text: 'At the fortieth second, the dust that has hung above the bed comes down — very softly, like the last of a snowfall — onto the blue blanket and the white stitched stars.' },
    { kind: 'narrate', text: 'At the fifty-ninth second, Colette Vire breathes out.' },
    { kind: 'line', who: 'teddy', text: 'Not twelve. This city has had quite enough of twelve. One o’clock. The first hour. The one he owes us.' },
    { kind: 'narrate', text: 'Aldric sets the long hand at the top and the short hand at the one, and drives the pin home with the heel of his palm.' },
    { kind: 'bell', strokes: 1, text: 'The Cathedral Clock strikes one.' },
    { kind: 'narrate', text: 'One. Not thirteen — one. The first hour of 1930, a year late and in a hurry; and behind it, like passengers who have waited all night on a cold platform, every hour the city missed comes crowding through the door at once.' },
    { kind: 'narrate', text: 'Down in Cathedral Square the chestnut brazier finally burns. The pyramid of oranges gives up and rolls. At the altar steps, Verger Abney finds his candle has burned down an inch, and weeps with relief at the sight of a little spent wax.' },
    { kind: 'narrate', text: 'On the roof two hundred crows take off at once, as though somebody has finally posted the letter they have been waiting a year to carry.' },
    { kind: 'bg', bg: 'parlour', tone: 'dawn' },
    { kind: 'narrate', text: 'Dawn comes to Vellmoor like a held breath let go. Lamps flare across the city. Names return to doorplates. Blank letters fill with ink again.' },
    { kind: 'narrate', text: 'It comes up out of the sea, over the breakwater, where Keeper Brine’s old light has turned round at last to face the ships. It crosses the mudflats and the stranded hulls, and the hulls lift, one by one, and creak, and remember that they float.' },
    { kind: 'narrate', text: 'It climbs Saltgate and the Cordwainers’ Steps, and Corvid Lane where every window has a name in it again; it runs along the Gloaming’s marquee like a finger along a line of print — and last of all it climbs the long cold face of the Cathedral Clock, numeral by brass numeral, until it reaches the glass.' },
    { kind: 'narrate', text: 'Behind the glass, the light comes in backwards through the numerals and lays them across the floor in gold: a XII across the fallen hands, a III over Aldric’s boots, a VI on the blue blanket, a little crooked, like a child’s drawing of the sun.' },
    { kind: 'narrate', text: 'Her eyes are grey. His colour. Columbine’s colour. They open slowly, the way a curtain opens in a theatre where the stagehands have been told to take their time.' },
    { kind: 'line', who: 'Colette', text: 'Papa. Look.' },
    { kind: 'line', who: 'Colette', text: '…It came.' },
    { kind: 'narrate', text: 'Aldous Vire, who has spent ten years making certain he would never hear those words again, hears them. He holds her hand. He does not draw the curtain. He looks where she is looking, and for the first time in ten years he lets the sun come all the way up.' },
    { kind: 'narrate', text: 'She turns her head — a very small turn — and finds the girl in red at the foot of the bed, caught mid-step, out of breath, though she has never breathed.' },
    { kind: 'line', who: 'Colette', text: 'Red suits you.' },
    { kind: 'narrate', text: 'Colette Vire opened her eyes once, at sunrise. She saw her father, and the doll he had made in her likeness, and she smiled. Then she slept.' },
    { kind: 'narrate', text: 'Dr. Halloway, sent for by Mrs. Pruitt, would write on the certificate: 1 January 1930, at eleven minutes past seven in the morning. Peacefully. And in the margin, in a different ink, where the form did not ask for it: She was watching the sunrise.' },
    { kind: 'narrate', text: 'Nobody stops the clocks.' },
    { kind: 'line', who: 'bastian', text: 'She told me to dance until morning. It is morning… and I do not want to stop.' },
    { kind: 'line', who: 'wren', text: 'Then don’t. Nobody is holding the strings now.' },
    { kind: 'narrate', text: 'In the west, the last stars are going out the ordinary way — not eaten by the dark, only outshone.' },
    { kind: 'line', who: 'odile', text: 'The stars are moving again, Keeper. All of them.' },
    { kind: 'line', who: 'odile', text: 'I read them once more, just now, before the light took them. Do you know what they said? Nothing at all. Only the weather. I have never been so glad to be told about the weather.' },
    { kind: 'narrate', text: 'In Corvin’s satchel a year of letters grows heavy all at once. Ink comes back into blank pages like colour into a cheek. Names surface at the bottom of them — signatures, addresses, rows of small crosses for kisses.', bg: 'street', tone: 'dawn' },
    { kind: 'narrate', text: 'The first letter of all — the one that came the first night, unsigned, about the lamps of Corvid Lane and the moths at the windows — has a name at the bottom now, in a firm round hand, and a postscript: Thank you for reading.' },
    { kind: 'narrate', text: 'Corvin reads the name aloud, once, quietly, to nobody. It is no one you would know. It is everything.' },
    { kind: 'line', who: 'wren', text: 'Delivered.' },
    { kind: 'narrate', text: 'At the harbour the tide comes in the whole way, all in one long grey breath, and floats every ship on the mud at once. Harbourmaster Marée stands on the quay in his nightshirt and watches his son walk down the slipway into the sea up to his knees.', bg: 'docks', tone: 'dawn' },
    { kind: 'line', who: 'ichabod', text: 'I didn’t call it, Father. It came on its own. All I did was say good morning.' },
    { kind: 'line', who: 'Harbourmaster Marée', text: 'Then say it again, lad. Louder. I’ve gone a year without hearing it.' },
    { kind: 'narrate', text: 'Later that morning Count Valerian Rosenthal walks down the empty aisle of the Gloaming and lays a rose at the lip of the stage — and another beside it, for a girl in row K who liked to count hair-pins.', bg: 'theatre', tone: 'dawn' },
    { kind: 'line', who: 'marigold', text: 'Gloria. Colette. There. I shall go on saying your names every night. Not to keep them — the dark cannot have them now — but because I like the sound of them, and I am old enough to do as I please.' },
    { kind: 'narrate', text: 'In the nave of St. Aldhelm’s, Isidore Vellum opens his cookery book to a clean margin and writes: 1 January 1930. Morning. Then, after some thought, he gives the sunrise a line to itself.', bg: 'clocktower', tone: 'dawn' },
    { kind: 'line', who: 'kit', text: 'Every road out of Vellmoor bent back at midnight. I wonder where they go at noon. Come along, cat. We have some walking to catch up on.' },
    { kind: 'line', who: 'evangeline', text: 'Hortensia. Captain Biscuit. Go on. She named you so you would come back. You don’t have to. But you may.' },
    { kind: 'narrate', text: 'Two doves go up from the cathedral steps into a sky that moves. Above them, in a ragged black line from the roof to the harbour, the crows are already writing something across the morning in a hand nobody can read.' },
    { kind: 'line', who: 'hesper', text: 'The map ends in the margin now. I have left it blank. I think, from now on, the margin is simply — tomorrow.' },
    { kind: 'narrate', text: 'That afternoon, at No. 9 Spindle Street, beneath a sign that reads A. VIRE & DAUGHTER · CLOCKMAKERS again, every letter of it, a man sits in the back room with the curtains wide open and writes a letter in a hand that will not stop shaking.', bg: 'parlour', tone: 'dawn' },
    { kind: 'narrate', text: 'The Dimming has let go of him. His name has come back to him the way it came back to the doorplates — a little faded, a little crooked, entirely his.' },
    { kind: 'line', who: 'Aldous Vire', text: 'You are a postman, Mr. Vesper. I should like to post something. I do not know the address.' },
    { kind: 'line', who: 'wren', text: 'I have delivered to worse. Give it here.' },
    { kind: 'letter', text: 'Colette — It came. You were right; it is mostly orange. Mrs. Pruitt was right as well, which she will never let me forget. I am sorry I kept it from you for ten years, and from everyone else for one. I shall watch it every morning now, on your behalf, and report.', sign: '— Papa' },
    { kind: 'letter', text: 'P.S. Columbine is keeping the red dress. I had not the heart to argue, and she did not ask.', sign: '— A.V.' },
    { kind: 'line', who: 'Aldous Vire', text: 'Aldric has the shop, if he will take it. I find I should like to sit in the window for a while and watch people ask one another the time. I never once let them. It seems a small thing to have taken from a city.' },
    { kind: 'narrate', text: 'At six o’clock Aldric Verdane climbs four hundred and thirteen steps — counting every one, from habit now and not from fear — and winds the Cathedral Clock by hand, as he did every Sunday for twenty years. It is a Wednesday. He does not care.', bg: 'clocktower', tone: 'dawn' },
    { kind: 'line', who: 'teddy', text: 'A good clock does not keep time. It keeps faith. …Go on, then, old girl. Keep it.' },
    { kind: 'bell', strokes: 6, text: 'Six o’clock. Exactly six. Not one more.' },
    { kind: 'narrate', text: 'On the roof above the north face, Corvin reads Aldous Vire’s letter aloud to the sky and the crows and whoever else is listening. He has always believed a letter read aloud has been delivered. Tonight, he needs to.' },
    { kind: 'line', who: 'wren', text: 'Delivered.' },
    { kind: 'line', who: 'bastian', text: 'Corvin. What do I do now? I was made for one person, and she’s gone.' },
    { kind: 'line', who: 'wren', text: 'You were made for one person. You were named by her, too — after the one who always gets away. I think she was telling you what to do next.' },
    { kind: 'line', who: 'bastian', text: 'Then I shall get away. Not from you. Only — onwards.' },
    { kind: 'line', who: 'bastian', text: 'Will you teach me to read the letters aloud? The way you do. I think I should like to be someone who says other people’s names.' },
    { kind: 'line', who: 'wren', text: 'It is the best work in the world. The pay is dreadful.' },
    { kind: 'title', kicker: 'EPILOGUE', title: 'One Grain Missing' },
    { kind: 'narrate', text: 'That evening, in a drawing room high above the Gloaming Theatre, a countess turns her hourglass over — and frowns.', bg: 'parlour', tone: 'cold' },
    { kind: 'narrate', text: 'The glass has run true all day, sixty grains to the minute, as it should. She has counted the minute Aldous gave back three times over. It is not sixty grains. It is fifty-nine.' },
    { kind: 'line', who: 'ottoline', text: 'Fifty-nine. Someone has had a second out of my minute. And I do not lend seconds.' },
    { kind: 'line', who: 'ottoline', text: 'Twelve strokes, and then one more. But Vire only ever rang twelve. I was there. I was watching his hands.' },
    { kind: 'line', who: 'ottoline', text: 'He let go of the rope after the twelfth. I saw him do it. His hands were in his lap, shaking, the way they shake still. And the bell rang anyway.' },
    { kind: 'line', who: 'ottoline', text: 'So who rang the thirteenth?' },
    { kind: 'narrate', text: 'In Corvin’s satchel, a new letter arrives. The envelope is blank. The paper is blank. Only the wax seal is real — a clock face with thirteen hours.', bg: 'street', tone: 'cold' },
    { kind: 'narrate', text: 'None of his crows will admit to carrying it. Sexton, who carries everything, turns his back and pretends very hard to be asleep.' },
    { kind: 'line', who: 'wren', text: 'No sender. No address. No ink.' },
    { kind: 'line', who: 'wren', text: '…And it’s warm. Like a letter that has only just been written.' },
    { kind: 'bell', strokes: 1, ominous: true, text: 'Somewhere in Vellmoor — not from the Cathedral — a bell strikes once.' },
    { kind: 'title', kicker: 'TO BE CONTINUED', title: 'The Thirteenth Bell', sub: 'Project Firefly · Chapter V' },
  ],
};

